/* Joomla Playground, heritage demo: the language switcher (position topbar) on the row of the site name, at the
   right. The header becomes a one-column grid; the switcher and the site name share its second row. On narrow
   screens the switcher stays above the site name, as Cassiopeia has it. */
@media (width >= 768px) {
  .container-header:has(.container-topbar .mod-languages) {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
  }

  .container-header:has(.container-topbar .mod-languages) > .grid-child:has(.navbar-brand),
  .container-header:has(.container-topbar .mod-languages) > .container-topbar {
    grid-row: 2;
    grid-column: 1;
  }

  .container-header .container-topbar:has(.mod-languages) {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    align-self: center;
    width: 100%;
    max-width: 1320px;
    margin: 0 auto;
    padding: .5em;
    background: none;
    /* Above the site name's row, which shares the cell; the site name's link stays clickable under the empty
       part of this row. */
    position: relative;
    z-index: 1;
    pointer-events: none;
  }

  .container-header .container-topbar .mod-languages {
    pointer-events: auto;
  }
}
